cd /tmp; mkdir -p dl && cd dl; curl -sL -m 60 -o il.docx "https://www.trustees.uillinois.edu/trustees/agenda/January-15-2026/06b-Jan-26-Approve-Tuition-AY26-27-attach.docx"; curl -sL -m 60 -o ilfee.docx "https://www.trustees.uillinois.edu/trustees/agenda/January-15-2026/07b-Jan-26-Approve-Student-Fees-AY26-27-attach.docx"; ls -la; cd /tmp; python3 -I - <<'E'
import zipfile,re
for f in ['dl/il.docx','dl/ilfee.docx']:
    try:
        x=zipfile.ZipFile(f).read('word/document.xml').decode()
        t=re.sub(r'</w:p>','\n',x);t=re.sub(r'<[^>]+>','',t)
        print(f,t[:2500]);print('-----')
    except Exception as e: print(f,e)
E

